sys_ui_action.script:
function onSubmit() {
    // MSSCUSTODY-4328
    var currentAssignee = g_form.getValue('assigned_to');
    if (currentAssignee != g_user.userID) {
        g_form.addErrorMessage('Only Assigned to User can submit the Bulk. Please refresh to get the bulk assigned.');
        return false;
    }
    var mandatoryfields = g_form.getMissingFields();
    if (mandatoryfields.length > 0) {
        g_form.addErrorMessage('The following mandatory fields are not filled in: ' + mandatoryfields.toString());
        return false;
    }

    if ((g_form.getValue('sub_outcome') === 'Self De-Link Trade' || g_form.getValue('sub_outcome') === 'Link Trade') &&
        g_form.getValue('trade_transaction_reference').startsWith('D') &&
        g_form.getValue('script_hold_indicator') !== 'N'
    ) {
        g_form.addErrorMessage("Scrip Hold Indicator at each trade level for Delivery transaction(s) must be 'N'. Please check");
        return false;
    }

    var reasonDesc = g_form.getValue("reason_description");
    g_form.hideFieldMsg("reason_description");
    if (reasonDesc.toString().indexOf('<') != -1 || reasonDesc.toString().indexOf('>') != -1) {
        g_form.showFieldMsg("reason_description", "Unable to submit, please update Reason Description to populate <xxx> section. Note that <> are also special characters which cannot be submitted.", "error");
        return false;
    }
    // Verify if reason description contains special characeters which are not accepted
    var RegularExp = /^[a-zA-Z0-9/\-?:().,'+\s]*$/i;
    var result = RegularExp.test(reasonDesc.toString());
    if (result == false) {
        g_form.showFieldMsg("reason_description", "Unable to submit. Special Characters are not permitted, please update the Reason Description using only Alphanumeric characters or /-?: ().,’+ or space.", "error");
        return false;
    }
    // Verify if Bk to Bk Info has <> 
    var bkTobk = g_form.getValue("bk_to_bk_info");
    g_form.hideFieldMsg("bk_to_bk_info");
    if (bkTobk.toString().indexOf('<') != -1 || bkTobk.toString().indexOf('>') != -1) {
        g_form.showFieldMsg("bk_to_bk_info", "Unable to submit, please update Bk to Bk Info field. Note that <,> are also special characters which cannot be submitted.", "error");
        return false;
    }
    // Verify if Bk to Bk Info contains special characeters which are not accepted
    var RegularExp_bk = /^[a-zA-Z0-9/\-?:().,'+\s]*$/i;
    var result_bk = RegularExp_bk.test(bkTobk.toString());
    if (result_bk == false) {
        g_form.showFieldMsg("bk_to_bk_info", "Unable to submit. Special Characters are not permitted, please update the Bk to Bk Info using only Alphanumeric characters or /-?: ().,’+ or space.", "error");
        return false;
    }


    //   g_form.clearMessages();
    var outcomeval = g_form.getValue('outcome').toString();

    //MSSCUSTODY-7266
    var subOutcomeval = g_form.getValue('sub_outcome').toString();
    if (outcomeval == 'Switch Maintenance' && subOutcomeval == 'Convert to Non-Switching Trade') {
        var amendCounterpartyCode = g_form.getDisplayBox('amend_counterparty_code_ref').value;
        if (!amendCounterpartyCode) {
            g_form.addErrorMessage('Enter CounterParty Code. It is a mandatory field.');
            return false;
        }

        var updateBulk = new GlideAjax("x_hsb11_mss_c_proc.MSSCustodyBulkUtils");
        updateBulk.addParam('sysparm_name', 'setBulkFieldValuesForSwitch');
        updateBulk.addParam('sysparm_recSysID', g_form.getUniqueValue());
        updateBulk.addParam('sysparm_counterpartyCodeRef', amendCounterpartyCode); //remote Table field
        updateBulk.getXMLAnswer(passValuetoBulkRecord);

        function passValuetoBulkRecord() {}

    }

    //MSSCUSTODY-7057: Linking
    if (outcomeval == 'Linking' && subOutcomeval == 'Link Trade') {
        var transRef = g_form.getDisplayBox('transaction_reference_link').value.toString();
        var scripHold = g_form.getValue('amend_script_hold_indicator').toString();

        if (transRef.indexOf('-D-') > -1 && scripHold != 'N') {
            g_form.addErrorMessage("Scrip Hold Indicator at each trade level for Delivery transaction(s) must be 'N' - Please check");
            return false;
        }
    }

    if ((g_form.getValue('state') == 2) && (g_scratchpad.blkTskRelated == 'Maker')) { // MSSCUSTODY-8743
        var eligbleCheck = new GlideAjax('x_hsb11_mss_c_proc.MSSCustodyAmendUtils');
        eligbleCheck.addParam('sysparm_name', 'evalAmendEligibility');
        eligbleCheck.addParam('sysparm_recOutcome', g_form.getValue('outcome'));
        eligbleCheck.addParam('sysparm_recSysID', g_form.getUniqueValue());
        eligbleCheck.addParam('sysparm_tableName', 'x_hsb11_hsbc_mss_o_hsbc_bulk_transaction');
        eligbleCheck.getXMLAnswer(checkIfFieldsModifiedForAmend);
    } else if (g_scratchpad.blkTskRelated == 'Checker') {
        gsftSubmit(null, g_form.getFormElement(), 'submit_checker');
    }


    function checkIfFieldsModifiedForAmend(check) {
        if (check.toString() == 'true') {
            //var trdSettlementCurr = g_scratchpad.settlementCurrency;
            //var trdSettlementDate = g_scratchpad.settlementDate;
            var tskAmendDate = g_form.getValue("amend_trade_date");
            var amendCurr = g_form.getValue("amend_settlement_currency");
            var amendSettAmt = g_form.getValue("amend_settlement_amount");
            var amendSettDate = g_form.getValue("settlement_date");
            var amendLocationCode = g_form.getValue("amend_location_code");
            var amendHmiIndicator = g_form.getValue("amend_hmi_indicator");
            //var tradeId = g_form.getValue("trade_id");
            var gdiIndicator = g_form.getValue("amend_gdi_indicator");
            var placeOfSettlementBic = g_form.getValue("amend_place_of_settlement_bic");
            var amendScriptHoldIndicator = g_form.getValue("amend_script_hold_indicator");
            var amendSellerBuyerBic = g_form.getValue("amend_seller_bic_buyer_bic");
            var amendDealPrice = g_form.getValue("amend_deal_price");
            var amendDealCurrency = g_form.getValue("amend_deal_currency");
            //var trdCashAccId = g_form.getValue("trade_id.cash_account_id");
            var amendBuyerSellerBic = g_form.getValue("amend_seller_bic_buyer_bic");
            var amendCustomerReference = g_form.getValue("customer_reference");
            var amendCashHoldIndicator = g_form.getValue("amend_cash_hold_indicator");
            var amendSuspenseAccNum = g_form.getValue("amend_suspense_account_number");
            var amendChargesType = g_form.getValue("amend_charges_type");
            var amendChargesCcy = g_form.getValue("amend_charges_ccy");
            var amendChargesAmt = g_form.getValue("amend_charges_amt");
            var amendDelivererReceivererBic = g_form.getValue("amend_deliverer_custodian_bic_receiver_custodian_bic");
            var accOfClient = g_form.getValue("amend_a_c_of_client")
            var amendCounterpartyRef = g_form.getValue("counterparty_reference");
            var amendCounterpartySettAccNum = g_form.getValue("amend_counterparty_settlement_account_number");
            var amendSellerBic = g_form.getValue("amend_buyer_bic"); //7133
            var amendReceivererBic = g_form.getValue("amend_receiver_custodian_bic"); //7133
            var amendSWH = g_form.getValue("amend_swh"); //7910
            var amendFA = g_form.getValue("amend_fa"); //8184

            // MSSCUSTODY-5983
            var amendSecurityID = g_form.getDisplayBox('amend_security_id_sec_id_ref').value;
            var amendCounterpartyCodeVal = g_form.getDisplayBox('amend_counterparty_code_ref').value;

            var bulk_field_group = g_form.getValue('bulk_field_group').toString();
            if (bulk_field_group == 'trade_settl_date') {
                var amendValidation = new GlideAjax("x_hsb11_mss_c_proc.MSSCustodyBulkUtils");
                amendValidation.addParam("sysparm_name", "amendValidationChecks");
                amendValidation.addParam("sysparm_bulkid", g_form.getUniqueValue());
                // amendValidation.addParam('sysparm_trdSettlementDate', trdSettlementDate);
                amendValidation.addParam('sysparm_taskAmendDate', tskAmendDate);
                amendValidation.addParam('sysparm_amendSettDate', amendSettDate);
                amendValidation.addParam('sysparm_bulkFieldGroup', bulk_field_group); //7910
                amendValidation.addParam('sysparm_amendSWH', amendSWH); //7910
                amendValidation.getXMLAnswer(responseCall);
            } else if (bulk_field_group == 'blank_trade_date') { //changes under 6832
                var amendValidation = new GlideAjax("x_hsb11_mss_c_proc.MSSCustodyBulkUtils");
                amendValidation.addParam("sysparm_name", "amendValidationChecks");
                amendValidation.addParam("sysparm_bulkid", g_form.getUniqueValue());
                amendValidation.getXMLAnswer(responseCall);
            } else if (bulk_field_group == 'location_gdi') {
                var amendValidation = new GlideAjax("x_hsb11_mss_c_proc.MSSCustodyBulkUtils");
                amendValidation.addParam("sysparm_name", "amendValidationChecks");
                amendValidation.addParam("sysparm_bulkid", g_form.getUniqueValue());
                amendValidation.addParam('sysparm_taskAmendLocationCode', amendLocationCode);
                amendValidation.addParam('sysparm_gdiIndicator', gdiIndicator);
                amendValidation.getXMLAnswer(responseCall);
            } else if (bulk_field_group == 'hmi_indicator​') {
                var amendValidation = new GlideAjax("x_hsb11_mss_c_proc.MSSCustodyBulkUtils");
                amendValidation.addParam("sysparm_name", "amendValidationChecks");
                amendValidation.addParam("sysparm_bulkid", g_form.getUniqueValue());
                amendValidation.addParam('sysparm_amendHmiIndicator', amendHmiIndicator);
                amendValidation.getXMLAnswer(responseCall);
            } else if (bulk_field_group == 'script_hold_indicator') {
                var amendValidation = new GlideAjax("x_hsb11_mss_c_proc.MSSCustodyBulkUtils");
                amendValidation.addParam("sysparm_name", "amendValidationChecks");
                amendValidation.addParam("sysparm_bulkid", g_form.getUniqueValue());
                amendValidation.addParam('sysparm_amendScriptHoldIndicator', amendScriptHoldIndicator);
                amendValidation.getXMLAnswer(responseCall);
            } else if (bulk_field_group == 'cash_hold_indicator') {
                var amendValidation = new GlideAjax("x_hsb11_mss_c_proc.MSSCustodyBulkUtils");
                amendValidation.addParam("sysparm_name", "amendValidationChecks");
                amendValidation.addParam("sysparm_bulkid", g_form.getUniqueValue());
                amendValidation.addParam('sysparm_amendCashHoldIndicator', amendCashHoldIndicator);
                amendValidation.getXMLAnswer(responseCall);
            } else if (bulk_field_group == 'beneficiary_details') {
                var amendValidation = new GlideAjax("x_hsb11_mss_c_proc.MSSCustodyBulkUtils");
                amendValidation.addParam("sysparm_name", "amendValidationChecks");
                amendValidation.addParam("sysparm_bulkid", g_form.getUniqueValue());
                amendValidation.addParam('sysparm_amendBuyerSellerBic', amendBuyerSellerBic);
                amendValidation.addParam('sysparm_placeOfSettlementBic', placeOfSettlementBic);
                amendValidation.addParam('sysparm_amendReceivererBic', amendReceivererBic); //7133
                amendValidation.addParam('sysparm_amendSellerBic', amendSellerBic); //7133
                amendValidation.addParam('sysparm_amendDelivererReceivererBic', amendDelivererReceivererBic);
                amendValidation.addParam('sysparm_accOfClient', accOfClient);
                if (g_form.getControl('amend_a_c_of_client')) {
                    amendValidation.addParam('sysparm_bulkFieldGroup', bulk_field_group);
                }
                amendValidation.getXMLAnswer(responseCall);
            } else if (bulk_field_group == 'customer_reference') {
                var amendValidation = new GlideAjax("x_hsb11_mss_c_proc.MSSCustodyBulkUtils");
                amendValidation.addParam("sysparm_name", "amendValidationChecks");
                amendValidation.addParam("sysparm_bulkid", g_form.getUniqueValue());
                amendValidation.addParam('sysparm_amendCustomerReference', amendCustomerReference);
                amendValidation.getXMLAnswer(responseCall);
            } else if (bulk_field_group == 'security_id') {
                var amendValidation = new GlideAjax("x_hsb11_mss_c_proc.MSSCustodyBulkUtils");
                amendValidation.addParam("sysparm_name", "amendValidationChecks");
                amendValidation.addParam("sysparm_bulkid", g_form.getUniqueValue());
                amendValidation.addParam("sysparm_amendSecurityID", amendSecurityID);
                if (g_form.getControl('amend_security_id_sec_id_ref')) {
                    amendValidation.addParam('sysparm_bulkFieldGroup', bulk_field_group);
                }
                amendValidation.getXMLAnswer(responseCall);
            } else if (bulk_field_group == 'amendment_charges') {
                var amendValidation = new GlideAjax("x_hsb11_mss_c_proc.MSSCustodyBulkUtils");
                amendValidation.addParam("sysparm_name", "amendValidationChecks");
                amendValidation.addParam("sysparm_bulkid", g_form.getUniqueValue());
                amendValidation.addParam('sysparm_amendChargesType', amendChargesType);
                amendValidation.addParam('sysparm_amendChargesCcy', amendChargesCcy);
                amendValidation.addParam('sysparm_amendChargesAmt', amendChargesAmt);
                amendValidation.getXMLAnswer(responseCall);
            } else if (bulk_field_group == 'counterparty_details') {
                var amendValidation = new GlideAjax("x_hsb11_mss_c_proc.MSSCustodyBulkUtils");
                amendValidation.addParam("sysparm_name", "amendValidationChecks");
                amendValidation.addParam("sysparm_bulkid", g_form.getUniqueValue());
                amendValidation.addParam('sysparm_amendCounterpartyRef', amendCounterpartyRef);
                amendValidation.addParam('sysparm_amendCounterpartySettAccNum', amendCounterpartySettAccNum);
                amendValidation.addParam("sysparm_amendCounterpartyCode", amendCounterpartyCodeVal);
                if (g_form.getControl('amend_counterparty_code_ref')) {
                    amendValidation.addParam('sysparm_bulkFieldGroup', bulk_field_group);
                }
                amendValidation.getXMLAnswer(responseCall);
            } else if (bulk_field_group == 'fa') { //8184
                var amendValidation = new GlideAjax("x_hsb11_mss_c_proc.MSSCustodyBulkUtils");
                amendValidation.addParam("sysparm_name", "amendValidationChecks");
                amendValidation.addParam('sysparm_bulkFieldGroup', bulk_field_group);
                amendValidation.addParam("sysparm_bulkid", g_form.getUniqueValue());
                amendValidation.addParam('sysparm_amendFA', amendFA);
                amendValidation.getXMLAnswer(responseCall);
            } else if (bulk_field_group == 'iss') { //8184
                var amendValidation = new GlideAjax("x_hsb11_mss_c_proc.MSSCustodyBulkUtils");
                amendValidation.addParam("sysparm_name", "amendValidationChecks");
                amendValidation.addParam("sysparm_bulkid", g_form.getUniqueValue());
                amendValidation.getXMLAnswer(responseCall);
            }
            //g_form.addErrorMessage("amend 142");
            // }

            //
        } else {

            var gajaxHandler = new GlideAjax("x_hsb11_mss_c_proc.MSSCustodyBulkUtils");
            gajaxHandler.addParam("sysparm_name", "isHandlerInProgress");
            gajaxHandler.addParam("sysparm_bulkid", g_form.getUniqueValue());
            gajaxHandler.getXMLAnswer(resHandler);
        }
    }

}

