function responseCall(answer) {


    if (answer.length > 98) { //to limit if there are any warnings
        g_form.addErrorMessage(answer);
        return false;
    } else {
        //passing the amend Values to update bulk MSSCUSTODY-6022
        //handling the remote table fields
        var securityID = g_form.getDisplayBox('amend_security_id_sec_id_ref').value ? g_form.getDisplayBox('amend_security_id_sec_id_ref').value : g_form.getValue('security_id_sec_id');
        var counterpartyCodeRef = g_form.getDisplayBox('amend_counterparty_code_ref').value ? g_form.getDisplayBox('amend_counterparty_code_ref').value : g_form.getValue('amend_counterparty_code');
        var switchAccRef = g_form.getDisplayBox('amend_switch_account_ref').value ? g_form.getDisplayBox('amend_switch_account_ref').value : g_form.getValue('amend_switch_account');
        //handling the remote table fields


        var trdDate = g_form.getValue('amend_trade_date');
        var settlementDate = g_form.getValue('settlement_date');
        var settlementCurrency = g_form.getValue('amend_settlement_currency');
        var settlementAmount = g_form.getValue('amend_settlement_amount');
        var dealCurrency = g_form.getValue('amend_deal_currency');
        var dealPrice = g_form.getValue('amend_deal_price');
        var countRef = g_form.getValue('counterparty_reference');
        var cuRef = g_form.getValue('customer_reference');
        var locCode = g_form.getValue('amend_location_code');
        var hmiIndicator = g_form.getValue('amend_hmi_indicator');
        var scriptIndicator = g_form.getValue('amend_script_hold_indicator');
        var cashIndicator = g_form.getValue('amend_cash_hold_indicator');
        var amendGdiIndicator = g_form.getValue('amend_gdi_indicator');
        var payMethod = g_form.getValue('amend_payment_method');
        var switchIndic = g_form.getValue('amend_switch_indicator');
        var susAccNumber = g_form.getValue('amend_suspense_account_number');
        var counterpartySettAccNum = g_form.getValue('amend_counterparty_settlement_account_number');
        var accSwitch = g_form.getValue('amend_convert_to_account_switching');
        var accOfClient = g_form.getValue('amend_a_c_of_client');
        var receiverBic = g_form.getValue("amend_receiver_custodian_bic"); //Receiver Bic MSSCUSTODY-7158 
        var deliverBic = g_form.getValue("amend_deliverer_custodian_bic_receiver_custodian_bic"); //Deliverer Bic MSSCUSTODY-7158 
        var buyerBic = g_form.getValue("amend_buyer_bic"); //buyer Bic MSSCUSTODY-7158 
        var sellerBic = g_form.getValue("amend_seller_bic_buyer_bic"); //seller Bic MSSCUSTODY-7158
        var placeOfSettBic = g_form.getValue('amend_place_of_settlement_bic');
        var chargeType = g_form.getValue('amend_charges_type');
        var chargeCCY = g_form.getValue('amend_charges_ccy');
        var chargeAmt = g_form.getValue('amend_charges_amt');
        var amendNSSC = g_form.getValue('amend_nssc');
        var amendSwh = g_form.getValue('amend_swh'); //MSSCUSTODY-7515
        var amendFa = g_form.getValue('amend_fa'); //MSSCUSTODY-8151
        var amendISS = g_form.getValue('amend_iss'); //MSSCUSTODY-7240



        var updateBulk = new GlideAjax('x_hsb11_hsbc_mss_o.MSSAmendUtilsCore');
        updateBulk.addParam('sysparm_name', 'setBulkFieldValuesForAmend');
        updateBulk.addParam('sysparm_outcome', g_form.getValue('outcome'));
        updateBulk.addParam('sysparm_recSysID', g_form.getUniqueValue());
        updateBulk.addParam('sysparm_bulkGrp', g_form.getValue('bulk_field_group'));
        //alert(g_form.getValue('bulk_field_group'));
        updateBulk.addParam('sysparm_securityID', securityID); //remote Table field
        updateBulk.addParam('sysparm_trdDate', trdDate);
        updateBulk.addParam('sysparm_settlementDate', settlementDate);
        updateBulk.addParam('sysparm_settlementCurrency', settlementCurrency);
        updateBulk.addParam('sysparm_settlementAmount', settlementAmount);
        updateBulk.addParam('sysparm_dealCurrency', dealCurrency);
        updateBulk.addParam('sysparm_dealPrice', dealPrice);
        updateBulk.addParam('sysparm_countRef', countRef);
        updateBulk.addParam('sysparm_cuRef', cuRef);
        updateBulk.addParam('sysparm_locCode', locCode);
        updateBulk.addParam('sysparm_hmiIndicator', hmiIndicator);
        updateBulk.addParam('sysparm_scriptIndicator', scriptIndicator);
        updateBulk.addParam('sysparm_cashIndicator', cashIndicator);
        updateBulk.addParam('sysparm_gdiIndicator', amendGdiIndicator);
        updateBulk.addParam('sysparm_payMethod', payMethod);
        updateBulk.addParam('sysparm_switchIndic', switchIndic);
        updateBulk.addParam('sysparm_switchAccRef', switchAccRef); //remote Table field
        updateBulk.addParam('sysparm_susAccNumber', susAccNumber);
        updateBulk.addParam('sysparm_counterpartyCodeRef', counterpartyCodeRef); //remote Table field
        updateBulk.addParam('sysparm_counterpartySettAccNum', counterpartySettAccNum);
        updateBulk.addParam('sysparm_accSwitch', accSwitch);
        updateBulk.addParam('sysparm_accOfClient', accOfClient);
        updateBulk.addParam('sysparm_receiverBic', receiverBic); //Receiver Bic MSSCUSTODY-7158 
        updateBulk.addParam('sysparm_deliverBic', deliverBic); //Deliverer BicMSSCUSTODY-7158 
        updateBulk.addParam('sysparm_buyerBic', buyerBic); //buyer Bic MSSCUSTODY-7158 
        updateBulk.addParam('sysparm_sellerBic', sellerBic); //seller Bic MSSCUSTODY-7158 
        updateBulk.addParam('sysparm_placeOfSettBic', placeOfSettBic);
        updateBulk.addParam('sysparm_chargeType', chargeType);
        updateBulk.addParam('sysparm_chargeCCY', chargeCCY);
        updateBulk.addParam('sysparm_chargeAmt', chargeAmt);
        updateBulk.addParam('sysparm_amendNSSC', amendNSSC);
        updateBulk.addParam('sysparm_amendSwh', amendSwh); //MSSCUSTODY-7515
        updateBulk.addParam('sysparm_amendFa', amendFa); //MSSCUSTODY-8151
        updateBulk.addParam('sysparm_amendiss', amendISS); //MSSCUSTODY-8151
        updateBulk.getXMLAnswer(passValuestoBulkRec);
        //passing the amend Values to update bulk MSSCUSTODY-6022


        //MSSCUSTODY-6022
        function passValuestoBulkRec() {
            //
        }
        // //MSSCUSTODY-6022
    }

    var gajaxHandler = new GlideAjax("x_hsb11_mss_c_proc.MSSCustodyBulkUtils");
    gajaxHandler.addParam("sysparm_name", "isHandlerInProgress");
    gajaxHandler.addParam("sysparm_bulkid", g_form.getUniqueValue());
    gajaxHandler.getXMLAnswer(resHandler);
}

function resHandler(answer) {

    if (answer == "true" || answer == true) {
        g_form.addErrorMessage("Handler Tasks are currently in Progress for this Bulk.");
        return false;
    }
    var gajax = new GlideAjax("x_hsb11_mss_c_proc.MSSCustodyBulkUtils");
    gajax.addParam("sysparm_name", "getCountOfTask");
    gajax.addParam("sysparm_bulkid", g_form.getUniqueValue());
    gajax.getXMLAnswer(response);
}

function response(answer) {

    var outcomeval = g_form.getValue('outcome').toString();
    var outcome = g_form.getValue('outcome');

    // MSSCUSTODY-3282 - Verify Task Count before submitting the bulk
    // MSSCUSTODY-4282
    // var expectedTasksCount = g_form.getValue("active_trade_count");
    if (outcome == 'Amend Trade' && g_scratchpad.recreatedCheckerExist == true) {
        var expectedTasksCount = g_scratchpad.makerCount;
    } else {
        expectedTasksCount = g_scratchpad.active_trades; // added as part of MSSCUSTODY - 5407 & MSSCUSTODY-5580
    }
    // MSSCUSTODY 4282
    if (expectedTasksCount == 0) {
        g_form.addErrorMessage("This Bulk does not have any Trades Linked due to GHSS Update");
        return false;
    }

    var validOutcomes = [
        'Amend and CONF',
        'Confirm Trade',
        'Settle Trade',
        'Confirm and Settle Trade'
    ];

